.stage-spirit { width: 34px; height: 40px; flex: none; opacity: 0.82; }
.stage[data-state="active"] .stage-spirit { opacity: 1; }
.stage-copy { display: grid; gap: 0; min-width: 0; }
.stage-index { color: var(--text-dim); font-family: var(--font-mono); font-size: 0.58rem; letter-spacing: 0.08em; }
