.stage[data-state="complete"] .stage-state { color: var(--status-positive); }

.frame { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-4); margin-top: var(--space-4); align-items: start; }
.side { display: grid; gap: var(--space-4); align-content: start; min-width: 0; }

.panel,
.document {
