  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 54%);
}

.control-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--border-amber);
  border-radius: var(--radius-sm);
