}
.inspector-recovery p { color: var(--text-muted); font-size: 0.8rem; }
.inspector-recovery .action { margin-top: var(--space-2); }

/* ==========================================================================
   Recommendation preview
   ========================================================================== */

.recommendation-table {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 54%);
}

.recommendation-row {
  display: grid;
