.setup-panel { padding: var(--space-4); }
.setup-panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.setup-panel-head h3 { margin-top: var(--space-1); color: var(--paper); font-size: 1.18rem; }
.setup-note { margin-top: var(--space-3); color: var(--text-dim); font-size: 0.8rem; }

.copy-button {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-height: 40px;
  padding: 0 0.7rem;
  border: 1px solid var(--border);
