/* ==========================================================================
   Privacy, FAQ, final CTA, footer
   ========================================================================== */

.privacy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-4);
}

.privacy-card {
  position: relative;
  padding: var(--space-5);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: linear-gradient(150deg, rgb(20 28 47 / 62%), rgb(9 13 23 / 76%));
}

.privacy-number {
  color: rgb(185 164 255 / 44%);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}
.privacy-card h3 { margin-top: var(--space-2); color: var(--paper); font-size: 1.3rem; }
.privacy-card p { margin-top: var(--space-2); color: var(--text-muted); font-size: 0.88rem; }

.faq-list { display: grid; gap: var(--space-2); }
.faq-item {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgb(14 20 34 / 48%);
}

.faq-item summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  min-height: 58px;
