.stage-name { color: inherit; font-family: var(--font-display); font-size: 1rem; line-height: 1.1; }
.stage-state { color: var(--text-dim); font-family: var(--font-mono); font-size: 0.58rem; letter-spacing: 0.04em; text-transform: uppercase; }
