  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.stage-panel { display: grid; gap: var(--space-3); margin-top: var(--space-4); }
.panel-intro { display: flex; align-items: flex-start; gap: var(--space-3); }
.panel-intro > div { min-width: 0; flex: 1; }
.panel-intro h2 { color: var(--paper); font-size: 1.35rem; }
.panel-intro p { margin-top: var(--space-1); color: var(--text-muted); font-size: 0.88rem; }
.panel-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex: none;
  border: 1px solid var(--border-amber);
