}
.panel-badges { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }

label { display: grid; gap: var(--space-2); color: var(--text-muted); font-size: 0.84rem; font-weight: 600; }
textarea {
  width: 100%;
  min-height: 7rem;
  padding: var(--space-3);
  resize: vertical;
  border: 1px solid rgb(184 179 199 / 34%);
  border-radius: var(--radius-sm);
  background: rgb(5 7 13 / 68%);
  color: var(--text);
  font: inherit;
  line-height: 1.55;
  overflow-wrap: anywhere;
  transition: border-color var(--dur-fast) var(--ease-standard), box-shadow var(--dur-fast) var(--ease-standard);
}
textarea:focus-visible { border-color: var(--amber); box-shadow: 0 0 0 4px var(--focus-halo); outline: none; }

.actions,
.form-grid { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-top: var(--space-3); }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-4); margin-top: var(--space-4); }
.form-grid > div { display: grid; gap: var(--space-2); align-content: start; }

.banner {
  margin-top: var(--space-3);
  padding: var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: rgb(240 235 225 / 5%);
  color: var(--text-muted);
  font-size: 0.84rem;
  overflow-wrap: anywhere;
}
.banner.bad { border-color: rgb(255 180 168 / 32%); color: var(--status-danger); background: rgb(255 180 168 / 7%); }
.banner.good { color: var(--status-positive); }

.error-panel,
.warning-panel {
  display: flex;
  gap: var(--space-3);
  align-items: flex-start;
  margin-top: var(--space-3);
  padding: var(--space-3);
  border: 1px solid rgb(255 180 168 / 32%);
  border-radius: var(--radius-sm);
  background: rgb(255 180 168 / 7%);
  color: var(--text-muted);
  font-size: 0.84rem;
}
.error-panel svg,
.warning-panel svg { flex: none; color: var(--status-danger); margin-top: 0.1rem; }
.error-panel strong,
.warning-panel strong { color: var(--status-danger); }
.error-panel p,
.warning-panel p { margin-top: var(--space-1); }
.error-panel .action { margin-top: var(--space-2); }
.warning-panel { border-color: rgb(255 208 138 / 32%); background: rgb(255 208 138 / 6%); }
.warning-panel svg,
.warning-panel strong { color: var(--status-warning); }

.reading {
  max-height: 62vh;
  overflow: auto;
  padding: var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background:
    linear-gradient(180deg, rgb(240 235 225 / 7%), rgb(240 235 225 / 3%));
}
.prose { white-space: pre-wrap; overflow-wrap: anywhere; color: var(--text); font-family: var(--font-display); font-size: 1.02rem; line-height: 1.7; }

.proposal-card { display: grid; gap: var(--space-3); }
.proposal-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); }
.proposal-head h3 { color: var(--paper); font-size: 1.2rem; }
.open-questions { padding-top: var(--space-3); border-top: 1px dashed var(--border); }
.open-questions h4 { color: var(--amber); font-family: var(--font-mono); font-size: 0.7rem; letter-spacing: 0.08em; text-transform: uppercase; }
.open-questions ul { display: grid; gap: var(--space-1); margin-top: var(--space-2); padding-left: 1rem; }
.open-questions li { list-style: disc; color: var(--text-muted); font-size: 0.88rem; }

.section-reading { min-height: 10rem; }
.scope-card,
.capability-card { padding: var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-sm); background: rgb(5 7 13 / 38%); }
.scope-card p { margin-top: var(--space-1); color: var(--text); font-size: 0.9rem; }
.capability-card h3 { color: var(--paper); font-family: var(--font-ui); font-size: 0.9rem; }
.capability-card p { margin-top: var(--space-2); color: var(--text-muted); font-size: 0.84rem; }

.witness-draft { margin-top: var(--space-3); }
.witness-draft h2 { color: var(--paper); font-size: 1.15rem; margin-bottom: var(--space-2); }

.empty-state {
  display: grid;
  justify-items: center;
  gap: var(--space-2);
  padding: var(--space-5);
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-sm);
  background: rgb(5 7 13 / 28%);
  text-align: center;
}
.empty-glyph {
  width: 28px;
  height: 28px;
  border: 1px solid var(--border-violet);
  border-radius: 50%;
  background: radial-gradient(circle, rgb(185 164 255 / 28%), transparent 64%);
}
.empty-title { color: var(--text); font-weight: 700; font-size: 0.9rem; }
.empty-state p:last-child { max-width: 44ch; color: var(--text-dim); font-size: 0.8rem; }

.transcript-list { display: grid; gap: var(--space-3); }
.transcript-list li { padding-left: var(--space-3); border-left: 1px solid var(--border); }
.transcript-list p { margin-top: 2px; color: var(--text-muted); font-size: 0.8rem; overflow-wrap: anywhere; }

.workshop-loading {
  display: grid;
  justify-items: center;
  gap: var(--space-3);
  width: min(680px, calc(100% - 2rem));
  margin: var(--space-8) auto;
  padding: var(--space-7);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: rgb(14 20 34 / 54%);
  text-align: center;
}
.workshop-loading h1 { color: var(--paper); font-size: clamp(2rem, 5vw, 3rem); }
.workshop-loading p { color: var(--text-muted); }
.loading-spirit { width: 130px; }

/* ==========================================================================
   Responsive
   ========================================================================== */

@media (max-width: 1120px) {
  .spirit-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .controls-grid,
  .setup-grid { grid-template-columns: minmax(0, 1fr); }
  .controls-copy { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .fixture-note { grid-column: 1 / -1; }
}

@media (max-width: 960px) {
  .site-nav { display: none; }
  .positioning { grid-template-columns: minmax(0, 1fr); }
  .demo-intro { grid-template-columns: minmax(0, 1fr); }
  .demo-main-card { grid-template-columns: minmax(0, 1fr); }
  .demo-main-art { min-height: 260px; border-right: 0; border-bottom: 1px solid var(--border); }
  .state-gallery { grid-template-columns: minmax(0, 1fr); }
  .frame { grid-template-columns: minmax(0, 1fr); }
  .side { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .inspector-side { grid-template-columns: minmax(0, 1fr); }
  .outline-panel { order: 2; }
  .engine-panel { order: 1; }
}

@media (max-width: 720px) {
  .site-header-inner,
  .workshop-header-inner { gap: var(--space-3); width: min(100% - 1.25rem, 1240px); min-height: 64px; }
  .brand-tag { display: none; }
  .site-header-actions .text-button { display: none; }
  .site-header-actions .action { min-height: 40px; padding: 0.55rem 0.85rem; font-size: 0.82rem; }
  .workshop-header-actions a { display: none; }
  .engine-pill { padding: 0 0.6rem; font-size: 0.7rem; }

  .hero {
    width: calc(100% - 1rem);
    min-height: 720px;
    margin-top: var(--space-2);
    border-radius: var(--radius-lg);
  }
  .hero-media img { object-position: 72% center; }
  .hero-veil {
    background:
      linear-gradient(0deg, rgb(5 7 13 / 98%) 0%, rgb(5 7 13 / 82%) 48%, rgb(5 7 13 / 28%) 100%),
      linear-gradient(90deg, rgb(5 7 13 / 72%), transparent 70%);
  }
  .hero-inner { padding: 1.25rem 1.25rem 2rem; padding-top: 12rem; }
  .hero h1 { font-size: clamp(2.4rem, 10vw, 3.4rem); }
  .hero-actions { display: grid; width: 100%; }
  .hero-actions .action { width: 100%; }
  .hero-facts { gap: var(--space-3) var(--space-4); }

  .positioning,
  .section,
  .final-cta,
  .site-footer,
  .demo-page { width: calc(100% - 1.25rem); }
  .positioning { margin-top: var(--space-5); padding: var(--space-4); }

  .mode-grid,
  .privacy-grid,
  .recovery-grid { grid-template-columns: minmax(0, 1fr); }
  .controls-copy { grid-template-columns: minmax(0, 1fr); }

  .demo-stage { grid-template-columns: minmax(0, 1fr); }
  .demo-spirit { min-height: 180px; }
  .demo-controls { display: grid; }
  .demo-buttons { margin-left: 0; }
  .demo-controls .text-link { margin-left: 0; }

  .spirit-card-art { min-height: 210px; }
  .final-spirits { gap: 0; flex-wrap: wrap; }

  .form-grid { grid-template-columns: minmax(0, 1fr); }
  .stage-strip { overflow-x: auto; }
  .stage { min-width: 168px; padding: var(--space-2) var(--space-3); }
  .workshop { width: calc(100% - 1.25rem); padding-top: var(--space-3); }
  .workshop-titlebar { min-height: 120px; }
  .workshop-character { width: 86px; }
  .document-spirit { display: none; }
  .side { grid-template-columns: minmax(0, 1fr); }
  .document { padding: var(--space-4); }
  .recommendation-row { min-width: 760px; }
}

@media (max-width: 480px) {
  .spirit-grid { grid-template-columns: minmax(0, 1fr); }
  .hero-facts div { flex: 1 1 40%; }
  .panel-intro { flex-wrap: wrap; }
  .panel-badges { width: 100%; }
  .actions .action { flex: 1 1 auto; }
}

/* ==========================================================================
   Accessibility fallbacks
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

@media (prefers-contrast: more) {
  :root {
    --border: rgb(240 235 225 / 38%);
    --border-strong: rgb(240 235 225 / 62%);
    --text-muted: #ded8ce;
    --text-dim: #c3bdd0;
  }

  .document,
  .panel,
  .stage-strip,
  .mode-card,
  .spirit-card,
  .run-inspector,
  textarea { border-width: 2px; }

  .status-chip,
  .state-list li { border-width: 2px; }
}

@media (forced-colors: active) {
