  .stage,
  .status-chip,
  .setup-tab,
  .faq-item,
  .mode-card,
  .spirit-card,
  .run-inspector,
  .document,
  .panel { border: 1px solid ButtonText; }

  .spirit { forced-color-adjust: auto; }
  .hero-grain { display: none; }
  .status-dot { forced-color-adjust: auto; }
  .faq-mark::before,
  .faq-mark::after { background: ButtonText; }
}

@media print {
  .site-header,
  .workshop-header,
  .hero-media,
  .hero-grain,
  .final-spirits,
  .setup-dialog { display: none !important; }
  body { background: #fff; color: #111; }
  .hero { min-height: auto; border: 0; }
  .hero-veil { background: none; }
  .hero h1,
  .section-heading h2,
  .mode-card h3,
  .spirit-card-copy h3 { color: #111; }
}

