        <li><CheckCircle2 size={16} aria-hidden="true" /> Verify</li>
      </ol>

      {phase === "connect" ? (
        <div className="wizard-grid">
          <div className="wizard-card">
            <h2><PlugZap size={20} aria-hidden="true" /> 1. Start OpenCode</h2>
