  font-size: 1.05rem;
}

.settings-button {
  margin-left: auto;
}

.onboarding {
  display: grid;
  gap: var(--space-4);
  background: var(--surface);
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 16px;
  padding: var(--space-5);
}

.onboarding-head {
  display: flex;
  gap: var(--space-4);
  justify-content: space-between;
  align-items: start;
}

.onboarding h1 {
  margin-bottom: var(--space-2);
}

.wizard-steps {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
