  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-radius: 999px;
  background: var(--raised);
  color: var(--muted);
}

.wizard-steps li.current {
  color: var(--accent);
  outline: 1px solid var(--accent);
}

.wizard-steps li.done {
  color: var(--success);
}

.wizard-grid {
  display: grid;
  gap: var(--space-4);
}

.wizard-card {
  background: var(--bg);
  border: 1px solid rgb(184 175 202 / 28%);
  border-radius: 14px;
  padding: var(--space-4);
}

.wizard-card h2 {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.wizard-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-4);
