489: function spiritStateFor(
490:   project: WorkshopProject,
491:   section: WorkshopProject["sections"][number] | null,
492: ): SpiritState {
493:   if (project.stage === "ORACLE") {
494:     return project.product.status === "PROPOSED" ? "clarification" : "listening";
495:   }
496:   if (project.stage === "ARCHITECT") {
497:     return section && (section.status === "DRAFT" || section.status === "STALE") ? "drawing" : "approval";
498:   }
499:   if (project.stage === "MAKER") {
500:     const latest = [...project.operations].reverse().find((operation) => operation.kind === "maker");
501:     if (!latest) return "idle";
502:     if (latest.status === "WAITING_PERMISSION") return "permission";
503:     if (latest.status === "UNKNOWN") return "permission";
504:     if (latest.status === "FAILED" || latest.status === "CANCELLED") return "blocked";
505:     if (latest.status === "SUCCEEDED") return "success";
506:     return "building";
507:   }
508:   if (project.evidence.some((item) => item.result === "FAIL" || item.result === "INCONCLUSIVE")) return "warning";
509:   if (project.witnessDrafts.length > 0) return "evidence";
510:   return "scanning";
511: }

