/* ==========================================================================
   OpenCode onboarding and advanced controls — Ghostlight adaptation
   ========================================================================== */

.engine-dot.is-warn {
  background: var(--status-warning);
  box-shadow: 0 0 0 4px rgb(255 208 138 / 12%);
}

.workshop-onboarding {
  padding-top: var(--space-5);
}

.workshop-onboarding .onboarding {
  border-color: var(--border);
  border-radius: var(--radius-lg);
  background:
    radial-gradient(circle at 8% 0%, rgb(243 182 109 / 9%), transparent 24rem),
    linear-gradient(160deg, rgb(20 28 47 / 78%), rgb(5 7 13 / 94%));
  box-shadow: var(--shadow-2);
}

.onboarding h1 {
  color: var(--paper);
  font-size: clamp(2rem, 4vw, 3rem);
}

.onboarding .wizard-card {
  border-color: var(--border);
  border-radius: var(--radius-md);
  background: rgb(5 7 13 / 46%);
}

.onboarding .wizard-card h2 {
  color: var(--paper);
  font-family: var(--font-ui);
  font-size: 1rem;
  font-weight: 700;
}

.onboarding .wizard-steps li {
  border: 1px solid var(--border);
  background: rgb(20 28 47 / 60%);
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.onboarding .wizard-steps li.current {
  border-color: var(--border-amber);
  background: rgb(243 182 109 / 9%);
  color: var(--amber-bright);
  outline: none;
}

.onboarding .wizard-steps li.done {
  border-color: rgb(143 227 184 / 28%);
  color: var(--status-positive);
}

.onboarding .connection-summary {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: rgb(20 28 47 / 64%);
}

.onboarding .connection-summary.good { outline-color: rgb(143 227 184 / 44%); }
.onboarding .connection-summary.warn { outline-color: var(--border-amber); }
.onboarding .connection-summary.bad { outline-color: rgb(255 180 168 / 44%); }

.onboarding .model-option {
  border-color: var(--border);
  background: rgb(14 20 34 / 62%);
}

.onboarding .model-option.selected {
  border-color: var(--border-amber);
  background: rgb(243 182 109 / 7%);
}

.onboarding .command {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-terminal);
  color: var(--cyan);
}

.onboarding .diagnostics li,
.onboarding .advanced .compact-list li,
.onboarding .advanced .capability-grid li {
  border: 1px solid var(--border);
  background: rgb(5 7 13 / 38%);
}

.onboarding .note,
.onboarding .repair,
.onboarding .model-facts {
  color: var(--text-muted);
}

.workshop .advanced {
  margin-top: var(--space-4);
  border-color: var(--border);
  border-radius: var(--radius-md);
  background: linear-gradient(180deg, rgb(20 28 47 / 62%), rgb(9 13 23 / 82%));
  box-shadow: var(--shadow-1);
}

.workshop .advanced > summary {
  color: var(--amber-bright);
  font-weight: 600;
}

.workshop .advanced-section h3 {
  color: var(--paper);
  font-family: var(--font-ui);
  font-size: 0.95rem;
  font-weight: 700;
}

.workshop .advanced-section h4 {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.workshop .advanced .state-pill {
  border: 1px solid var(--border);
  background: rgb(5 7 13 / 48%);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.workshop .advanced .state-pill.connected { border-color: rgb(143 227 184 / 34%); }
.workshop .advanced .state-pill.degraded,
.workshop .advanced .state-pill.checking { border-color: var(--border-amber); }
.workshop .advanced .state-pill.authentication_required,
.workshop .advanced .state-pill.unavailable,
.workshop .advanced .state-pill.incompatible_version { border-color: rgb(255 180 168 / 34%); }

.workshop .permission-actions button,
.workshop .session-actions button,
.workshop .revert-controls button {
  border: 1px solid var(--border);
  background: rgb(20 28 47 / 78%);
  color: var(--text);
}

.workshop .permission-actions button.danger,
.workshop .session-actions button.danger,
.workshop .revert-controls button.danger {
  border-color: rgb(255 180 168 / 34%);
  color: var(--status-danger);
}
EOF
